cards.styles:
:host {
  display: block;
  width: 100%;
}
ha-card {
  display: flex;
  flex-direction: column;
  align-items: stretch;
  gap: 0;
  width: 100%;
  padding: 0;
  margin: 0;
  background: none;
  border: none;
  box-shadow: none;
  touch-action: manipulation;
}
.row {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 10px;
  width: 100%;
  padding: 0;
  margin: 0;
  align-items: stretch;
  justify-items: stretch;
}
.row + .row {
  margin-top: 10px;
}
remote-button {
  width: 100%;
  min-width: 0;
  aspect-ratio: 1.1 / 1;
  min-height: 118px;
  max-height: 142px;
  padding: 0;
  margin: 0;
  overflow: hidden;
  align-items: stretch;
  justify-content: stretch;
  background: var(--ha-card-background, var(--card-background-color, #fff));
  border: var(--ha-card-border-width, 1px) solid var(--ha-card-border-color, var(--divider-color, #e0e0e0));
  border-radius: var(--ha-card-border-radius, 12px);
  box-shadow: var(--ha-card-box-shadow, none);
  transition: transform 100ms ease, background-color 150ms ease, border-color 150ms ease;
  --icon-size: 44px;
  --icon-color: var(--state-icon-color, #44739e);
}
remote-button[pressed] {
  transform: scale(0.97);
}
remote-button::part(button) {
  flex: 1 1 auto;
  width: 100%;
  height: 100%;
  padding: 12px 8px;
  gap: 6px;
  box-sizing: border-box;
  border-radius: inherit;
  overflow: hidden;
  justify-content: center;
  align-items: center;
  font-family: inherit;
  touch-action: manipulation;
  user-select: none;
  -webkit-user-select: none;
}
remote-button::part(icon) {
  flex-shrink: 0;
}
remote-button::part(label) {
  display: block;
  width: 100%;
  max-width: 100%;
  height: auto;
  line-height: 1.3;
  margin: 0;
  padding: 0 4px;
  box-sizing: border-box;
  font-family: inherit;
  font-size: 14px;
  font-weight: 500;
  color: var(--primary-text-color);
  text-align: center;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}
@media (max-width: 600px) {
  remote-button {
    aspect-ratio: 1.18 / 1;
    min-height: 88px;
    max-height: 102px;
    --icon-size: 36px;
  }
  remote-button::part(button) {
    padding: 8px 4px;
    gap: 6px;
  }
  remote-button::part(label) {
    font-size: 13px;
  }
}

